    // Location Manager

 to get user's location
    let locationManager = CLLocationManager()
    locationManager.requestWhenInUseAuthorization()

    // Get user's location
    if let location = locationManager.location {
        let latitude = location.coordinate.latitude
        let longitude = location.coordinate.longitude

        // Use location to fetch localized news
        let apiKey = "YOUR_API_KEY"
        let urlString = "https://api.example.com/news?latitude=\(latitude)&longitude=\(longitude)&api_key=\(apiKey)"

        if let url = URL(string: urlString) {
            do {
                let (data, _) = try URLSession.shared.data(from: url)
                let newsStories = try JSONDecoder().decode([String].self, from: data)
                return newsStories
            } catch {
                print("Error fetching news: \(error)")
                return []
            }
        } else {
            print("Invalid URL")
            return []
        }
    } else {
        print("Location not available")
        return []
    }
}

